const FIELD_AREA = /description|findings|response_text|summary|reason|basis|ground|assessment|note/;
const Tabs = ({ tabs, tab, setTab }) => <div className="tabs">{tabs.map(([k, l]) => <button key={k} className={tab === k ? 'on' : ''} onClick={() => setTab(k)}>{tx(l)}</button>)}</div>;
const Empty = ({ n }) => (n ? null : <p className="muted">{tx('Nothing to show yet.')}</p>);
