    <div className="bar"><div><h3 style={{ margin: 0 }}>{c.ref_no}</h3><small className="muted">{ctLabel(c.case_type)} · {c.full_name} ({c.employee_no}) · {c.staff_position_no ? tx('Position no.') + ' ' + c.staff_position_no : tx('Position number not recorded')}</small></div><Pill s={c.stage} /></div>
    {c.confidential && <div className="warnbox">{tx('Confidential case: restricted access, every view is recorded.')}</div>}
    {c.authority && <p className="muted">{tx('Deciding authority')}: <b>{tx('authority.' + c.authority.permission)}</b></p>}
    {c.case_type === 'recommendation_letter' && ['recommended', 'approved', 'completed'].includes(c.stage) && can(user, 'cases.manage') && <p className="ok">{tx('The recommendation has been given. The Work Experience Certificate is now enabled for this employee and its draft has been prepared.')} <a href="/work-certificates">{tx('Open Work Experience Certificate')}</a></p>}
